    <article class="fa-oc-kpi"><span>۷ روز اخیر</span><strong><?php echo wp_kses_post($page->money((float)$week['revenue'])); ?></strong><small><?php echo esc_html((string)$week['orders']); ?> سفارش</small></article>
    <article class="fa-oc-kpi"><span>۳۰ روز اخیر</span><strong><?php echo wp_kses_post($page->money((float)$month['revenue'])); ?></strong><small><?php echo esc_html((string)$month['orders']); ?> سفارش</small></article>
