<section class="fa-oc-panel">
    <form class="fa-oc-toolbar" method="get" action="<?php echo esc_url(admin_url('admin.php')); ?>"><input type="hidden" name="page" value="fa-order-center"><label class="screen-reader-text" for="fa-oc-search">جستجوی سفارش</label><input id="fa-oc-search" type="search" name="s" value="<?php echo esc_attr($search); ?>" placeholder="شماره سفارش، نام یا ایمیل مشتری…"><label class="screen-reader-text" for="fa-oc-status">فیلتر وضعیت</label><select id="fa-oc-status" name="status"><option value="">همه وضعیت‌ها</option><?php foreach ($statuses as $statusKey => $statusLabel) : $value = $page->normalizeStatus((string)$statusKey); ?><option value="<?php echo esc_attr($value); ?>" <?php selected($page->normalizeStatus($status), $value); ?>><?php echo esc_html($statusLabel); ?></option><?php endforeach; ?></select><button type="submit" class="button button-primary">جستجو</button><?php if ($search !== '' || $status !== '') : ?><a class="button" href="<?php echo esc_url($baseUrl); ?>">پاک‌کردن فیلتر</a><?php endif; ?></form>
