    <?php if ($result['pages'] > 1) : ?><nav class="fa-oc-pagination" aria-label="صفحات سفارش‌ها"><?php echo wp_kses_post(paginate_links(['base'=>add_query_arg(['page'=>'fa-order-center','paged'=>'%#%','s'=>$search,'status'=>$status], admin_url('admin.php')),'format'=>'','current'=>$result['page'],'total'=>$result['pages'],'type'=>'list','prev_text'=>'قبلی','next_text'=>'بعدی'])); ?></nav><?php endif; ?>
